// WSK-12 -- STEP 1, and the one the whole ticket exists to get right: verify the HMAC on the
// RAW REQUEST BYTES, BEFORE any JSON.parse. `options.rawBody: true` on the Webhook node above
// puts the exact wire bytes (base64) at `binary.data.data`; `json.body` is n8n's OWN pre-parsed
// copy and is NEVER read by this node -- reading it here would defeat the entire point (the
// ticket's own words: "verify the MAC on raw bytes before JSON parsing, or the signature is
// meaningless"). Mirrors webdesk/api/src/events/zoneb-event-signature.ts's `verifySignature()`
// byte-for-byte (that file is the reference implementation this Code node hand-transliterates --
// see its header for why the two cannot share an import across the zone boundary). Returns a
// verdict object; the NEXT node (an IF) branches on it -- this Code node never throws, per the
// estate's own doctrine that a 4xx-shaped refusal is an expected outcome routed with IF, not an
// error-output path (root n8n-error-handling convention).
const item = $input.first();
const headers = item.json.headers || {};
const timestampHeader = headers['x-webdesk-timestamp'];
const signatureHeader = headers['x-webdesk-signature'];
const secret = $env.WEBDESK_EVENT_SECRET;

const rawBase64 = item.binary && item.binary.data && item.binary.data.data;
if (!rawBase64) {
  return [{ json: { valid: false, reason: 'raw body missing -- rawBody option not enabled or empty body' } }];
}
const rawBody = Buffer.from(rawBase64, 'base64').toString('utf8');

if (!secret) {
  return [{ json: { valid: false, reason: 'WEBDESK_EVENT_SECRET is not configured on this n8n instance' } }];
}

if (!timestampHeader || !/^\d+$/.test(timestampHeader)) {
  return [{ json: { valid: false, reason: 'missing or malformed timestamp header' } }];
}
const ts = Number(timestampHeader);
const toleranceMs = Number($env.WEBDEV_ZONEB_EVENT_TOLERANCE_MS || 300000);
if (Math.abs(Date.now() - ts) > toleranceMs) {
  return [{ json: { valid: false, reason: 'stale timestamp -- outside the replay-tolerance window' } }];
}

if (!signatureHeader || !signatureHeader.startsWith('sha256=')) {
  return [{ json: { valid: false, reason: 'malformed signature header' } }];
}
const providedHex = signatureHeader.slice('sha256='.length);
if (!/^[0-9a-f]+$/i.test(providedHex)) {
  return [{ json: { valid: false, reason: 'malformed signature header' } }];
}

const crypto = require('crypto');
const expectedHex = crypto.createHmac('sha256', secret).update(`${timestampHeader}.${rawBody}`, 'utf8').digest('hex');
const providedBuf = Buffer.from(providedHex, 'hex');
const expectedBuf = Buffer.from(expectedHex, 'hex');
if (providedBuf.length !== expectedBuf.length || !crypto.timingSafeEqual(providedBuf, expectedBuf)) {
  return [{ json: { valid: false, reason: 'signature mismatch' } }];
}

return [{ json: { valid: true, rawBody } }];

// WSK-12 -- STEP 2: NOW it is safe to JSON.parse (HMAC already verified on the raw bytes by the
// previous node). Mirrors platform-nest's `validateZoneBEvent()`
// (platform-nest/src/modules/webdev/zoneb-event-schema.ts) byte-for-byte -- that file is the
// reference implementation this Code node hand-transliterates, same duplication-across-the-zone-
// boundary reasoning as the HMAC step. Zone A ALSO re-validates server-side (defense in depth) --
// this is not the only wall, it is the first one, cheap enough to reject obviously-malformed
// traffic before ever spending an mcp-hub round trip.
const KINDS = ['form.received', 'deploy.done', 'promote.done', 'rollback.done', 'contract.published', 'alert.raised'];

let envelope;
try {
  envelope = JSON.parse($json.rawBody);
} catch (e) {
  return [{ json: { valid: false, reason: 'body is not valid JSON' } }];
}
if (typeof envelope !== 'object' || envelope === null || Array.isArray(envelope)) {
  return [{ json: { valid: false, reason: 'body must be a JSON object' } }];
}
if (!envelope.eventId || typeof envelope.eventId !== 'string') {
  return [{ json: { valid: false, reason: 'eventId is required' } }];
}
if (!KINDS.includes(envelope.kind)) {
  return [{ json: { valid: false, reason: `kind must be one of: ${KINDS.join(', ')}` } }];
}
if (!envelope.tenantId || typeof envelope.tenantId !== 'string') {
  return [{ json: { valid: false, reason: 'tenantId is required' } }];
}
if (!envelope.originSite || typeof envelope.originSite !== 'string') {
  return [{ json: { valid: false, reason: 'originSite is required' } }];
}
if (!envelope.occurredAt || isNaN(Date.parse(envelope.occurredAt))) {
  return [{ json: { valid: false, reason: 'occurredAt must be a parseable ISO timestamp' } }];
}
if (typeof envelope.data !== 'object' || envelope.data === null || Array.isArray(envelope.data)) {
  return [{ json: { valid: false, reason: 'data must be a JSON object' } }];
}
if (envelope.kind === 'form.received') {
  const d = envelope.data;
  if (!d.siteSlug || !d.formId || !d.submissionId || typeof d.hasAttachments !== 'boolean') {
    return [{ json: { valid: false, reason: 'form.received data must carry siteSlug, formId, submissionId, hasAttachments' } }];
  }
}

return [{ json: { valid: true, envelope } }];

// WSK-12 -- STEP 3, the gate. Day-one gate mirroring on-inbound-lead.json's own INGEST_ENABLED
// doctrine exactly: inert until explicitly enabled, because the tool this step calls
// (`webdev.recordZoneBEvent`) and the automation identity that calls it (`wf:webdesk-zoneb-intake`)
// are WSK-19/31's build, not this ticket's -- see the WSK-12 report for the exact
// `mcp-hub/src/automation-policy.ts` allow-list entry and `webdevModule.mcpTools` addition that
// make this call reachable. Enabling this flag before those land means every call 403s at the hub
// (scoped-identity denial), which is the correct fail-closed outcome, not a workflow bug.
if ($env.WEBDEV_ZONEB_INTAKE_ENABLED !== '1') {
  throw new Error('wd-zoneb-intake: MCP dedup call disabled (WEBDEV_ZONEB_INTAKE_ENABLED != 1) -- gated until WSK-19/31 land webdev.recordZoneBEvent + the wf:webdesk-zoneb-intake account');
}
const envelope = $json.envelope;
return [{
  json: {
    envelope,
    mcpBody: JSON.stringify({
      jsonrpc: '2.0',
      id: 1,
      method: 'tools/call',
      params: {
        name: 'webdev.recordZoneBEvent',
        arguments: {
          tenantId: envelope.tenantId,
          eventId: envelope.eventId,
          kind: envelope.kind,
          originSite: envelope.originSite,
          occurredAt: envelope.occurredAt,
          data: envelope.data,
        },
      },
    }),
  },
}];

// WSK-12 -- STEP 4: route on the dedup outcome (§10: "form.received -> notification"). Parses
// mcp-hub's tools/call response (an MCP content envelope, same shape wd-digests.json's own
// "Parse notify result" node already unwraps) and decides whether a notify call is warranted.
// Deliberately narrow: only form.received facts that were a GENUINE new insert (never a
// deduped replay) are candidates, and only when a recipient has actually been configured --
// there is no per-tenant recipient-routing design yet (WSK-24's Sites tab is unbuilt), so this
// flow does not invent one. Absent WEBDEV_ZONEB_NOTIFY_RECIPIENT_ID, the fact still lands in
// webdev_zoneb_event_log (the durable, always-true outcome) and simply raises no notification --
// never a silent drop of the fact itself, only of the best-effort notice on top of it.
let parsed;
try {
  const raw = $json.data || $json.body || $json;
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const outer = JSON.parse(text);
  const contentText = outer.result && outer.result.content && outer.result.content[0] && outer.result.content[0].text;
  parsed = contentText ? JSON.parse(contentText) : outer.result;
} catch (e) {
  parsed = { inserted: false, id: null, parseError: String(e) };
}

const envelope = $('Gate + build MCP call').first().json.envelope;
const shouldNotify = envelope.kind === 'form.received' && parsed && parsed.inserted === true && !!$env.WEBDEV_ZONEB_NOTIFY_RECIPIENT_ID;

return [{ json: { envelope, outcome: parsed, shouldNotify } }];
